gear:_resolve_row.text:
func _resolve_row(lot_ref: Vector2i) -> int:
	"""The live row whose RECORDED identity is exactly `lot_ref`, or NULL_ROW.

	The derived lookup never substitutes for the row's recorded full identity. A stale lot
	handle, wrong index target or unoccupied row resolves to nothing without allocating.
	"""
	if lot_ref.x < 0 or lot_ref.x >= LOT_CAPACITY or lot_ref.y <= NULL_GENERATION:
		return NULL_ROW
	var row: int = _resolve_row_by_lot_slot(lot_ref.x)
	return row if row != NULL_ROW and _lot_generation[row] == lot_ref.y else NULL_ROW

gear:owner_of.text:
func owner_of(lot_ref: Vector2i) -> Vector2i:
	"""The recorded owner EntityRef, or NULL_REF when the gear is unowned or unknown.

	NULL_REF here is the GDD's own null reference, not a failure code: `has_gear()` distinguishes
	"no such gear" from "gear with no owner".
	"""
	var row: int = _resolve_row(lot_ref)
	if row == NULL_ROW:
		return NULL_REF
	return Vector2i(_owner_slot[row], _owner_generation[row])

haul_carry:carried_lot.text:
func carried_lot(hauler_slot: int) -> Vector2i:
	"""The first lot in the hauler's satchel -- one item lot per haul (H2) -- or the null ref."""
	var satchel: Vector2i = satchel_of(hauler_slot)
	return NULL_REF if satchel == NULL_REF else _inventory.container_first_lot(satchel)

haul_carry:satchel_of.text:
func satchel_of(hauler_slot: int) -> Vector2i:
	"""The live satchel the hauler carries, or the null ref (none, or a stale pair)."""
	if _residents == null or _inventory == null:
		return NULL_REF
	var satchel: Vector2i = _residents.satchel_of(hauler_slot)
	return satchel if _owns_live_satchel(hauler_slot, satchel) else NULL_REF

inventory:is_container_valid.text:
func is_container_valid(container_ref: Vector2i) -> bool:
	"""True when the ref names a live container at the generation it was issued for."""
	var slot: int = container_ref.x
	if slot < 0 or slot >= _c_capacity:
		return false
	return _c_live[slot] == 1 and _c_generation[slot] == container_ref.y

inventory:is_satchel.text:
func is_satchel(container_ref: Vector2i) -> bool:
	"""True for a live satchel row: one `create_satchel()` minted."""
	return is_container_valid(container_ref) and _c_policy[container_ref.x] == POLICY_SATCHEL
